structs.declaration:
pub enum ToolSensitivity {
    /// 低敏感 - 直接执行
    #[default]
    Low,
    /// 中敏感 - 根据用户配置决定
    Medium,
    /// 高敏感 - 必须审批
    High,
}

pub enum ToolConcurrency {
    /// 只读工具 - 可并行 + 瞬时错误可自动重试
    ReadOnly,
    /// 并行安全（有隔离副作用）- 可并行，不自动重试
    SafeParallel,
    /// 串行（默认，保守）
    #[default]
    Serial,
}

pub struct HostRequest {
    /// 桥通道名（如 `acr_bridge_call`、`mcp-bridge-request`）。
    pub channel: String,
    /// 请求载荷。
    pub payload: Value,
    /// 可选超时（毫秒）。
    #[serde(skip_serializing_if = "Option::is_none")]
    pub timeout_ms: Option<u64>,
}

pub struct ImageGenOptions {
    /// 图片宽度
    #[serde(skip_serializing_if = "Option::is_none")]
    pub width: Option<u32>,

    /// 图片高度
    #[serde(skip_serializing_if = "Option::is_none")]
    pub height: Option<u32>,

    /// 生成数量
    #[serde(skip_serializing_if = "Option::is_none")]
    pub n: Option<u32>,

    /// 模型 ID
    #[serde(skip_serializing_if = "Option::is_none")]
    pub model: Option<String>,

    /// 风格
    #[serde(skip_serializing_if = "Option::is_none")]
    pub style: Option<String>,

    /// 质量
    #[serde(skip_serializing_if = "Option::is_none")]
    pub quality: Option<String>,
}

pub struct ApprovalRequest {
    /// 会话 ID
    pub session_id: String,
    /// 工具调用 ID
    pub tool_call_id: String,
    /// 工具名称
    pub tool_name: String,
    /// 工具参数
    pub arguments: Value,
    /// 敏感等级
    pub sensitivity: String,
    pub permission_preset: crate::chat_v2::types::PermissionPreset,
    /// 兼容旧前端的人类可读描述。
    ///
    /// 当前协议不向 Rust 传递 UI locale；新版前端按 tool_name + arguments
    /// 本地化展示，本字段仅在翻译资源缺失或旧客户端中回退使用。
    pub description: String,
    /// 超时时间（秒）
    pub timeout_seconds: u32,
    /// 本地 runtime 审批作用域摘要（例如 shell 的 root/cwd/command scope）
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub runtime_scope: Option<RuntimeApprovalScope>,
}

pub struct ApprovalResponse {
    /// 会话 ID
    pub session_id: String,
    /// 工具调用 ID
    pub tool_call_id: String,
    /// 工具名称（用于"记住选择"功能）
    pub tool_name: String,
    /// 是否批准
    pub approved: bool,
    /// 拒绝原因
    pub reason: Option<String>,
    /// 是否记住选择（全局持久化）
    pub remember: bool,
    /// 🆕 审批三档分级：是否仅在本会话内记住选择（工具级，内存态，不持久化）
    #[serde(default)]
    pub remember_session: bool,
}

pub enum ShellCommandGuardEffect {
    Allow,
    Ask,
    Deny,
}

pub struct ShellCommandGuardDecision {
    pub effect: ShellCommandGuardEffect,
    pub reason: &'static str,
}

pub enum ScheduleKind {
    #[default]
    Daily,
    Weekly,
    Weekdays,
    Monthly,
    /// 周期间隔调度（每 N 分钟），供心跳等场景使用
    Interval,
    /// 一次性任务：在 `date` + `time`（`timezone` 或系统本地时区）执行一次，
    /// 触发即消耗（claim 时 next_run_at 置 NULL），成功终态后自动 enabled=0
    Once,
}

pub enum CatchUpPolicy {
    Skip,
    #[default]
    RunOnce,
    CatchUpAll,
}

pub struct AutomationSchedule {
    pub kind: ScheduleKind,
    /// 24h `HH:MM`（daily/weekly 必填；interval 可为空）
    #[serde(default)]
    pub time: String,
    /// 0=Sunday … 6=Saturday (required when kind=weekly, unless `weekdays` is set)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub weekday: Option<u8>,
    /// weekly 调度的一周多天扩展（编号口径与 `weekday` 完全一致：0=Sunday … 6=Saturday）。
    /// 与单数 `weekday` 同时存在时以 `weekdays` 优先；缺失时行为与旧版单日一致，
    /// 存量 schedule JSON 无该字段可原样解析（serde default = None）。
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub weekdays: Option<Vec<u8>>,
    /// monthly 调度的日期（1-31；短月份自动落在该月最后一天）
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub day_of_month: Option<u8>,
    /// 间隔分钟数（kind=interval 必填，范围 5–1440）
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub interval_minutes: Option<u32>,
    /// 一次性任务日期 `YYYY-MM-DD`（kind=once 必填）
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub date: Option<String>,
    /// IANA 时区，例如 Asia/Shanghai；为空时兼容旧数据并使用系统本地时区。
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub timezone: Option<String>,
}

pub enum AutomationActionType {
    /// 仅发系统通知 + 建待办（v1 行为）
    #[default]
    Notify,
    /// 创建隔离会话并真跑一轮 headless agent turn
    AgentTurn,
}

pub enum AutomationRootAccess {
    ReadOnly,
    ReadWrite,
}

pub struct AutomationRuntimeRoot {
    pub root_id: String,
    pub access: AutomationRootAccess,
}

pub struct BudgetLimitsSnapshot {
    pub max_tool_calls: u64,
    pub max_tokens: u64,
    pub max_wall_clock_secs: u64,
}

pub struct BudgetUsageSnapshot {
    pub tool_calls: u64,
    pub tokens_in: u64,
    pub tokens_out: u64,
    /// 快照时刻已耗时秒数（审计可读性；恢复的权威锚点是 `created_at_unix`）。
    pub wall_clock_secs: u64,
    /// 账本创建锚点（unix 秒）。恢复时据此推算累计耗时（停机期间继续
    /// 计时），超时的树恢复即 exhausted。
    pub created_at_unix: i64,
}

pub struct DispatcherInfo {
    pub owner: String,
    pub tick_interval_ms: u64,
    pub lease_secs: i64,
    pub max_attempts: i64,
}

pub enum ConnectorOperationState {
    /// 预览已创建，等待用户确认。
    Draft,
    /// 用户已确认（绑定 preview_sha256，受 TTL 限制）。
    Confirmed,
    /// 已落库、正在调用 provider。
    Submitting,
    /// provider 调用成功（终态）。
    Committed,
    /// 进程在 submitting 期间退出（或 provider 调用结果未知），远端结果未知
    /// （经 provider lookup 核销为 committed/failed）。
    OutcomeUnknown,
    /// provider 调用明确失败（终态）。
    Failed,
}

pub struct WebhookConfig {
    pub endpoint: String,
    pub secret_setting_key: String,
}

pub struct OsIdentity {
    /// `std::env::consts::OS`（如 `macos` / `linux` / `windows`）。
    pub os: String,
    /// `std::env::consts::ARCH`（如 `aarch64` / `x86_64`）。
    pub arch: String,
    /// `std::env::consts::FAMILY`（如 `unix` / `windows`）。
    pub family: String,
}

pub struct RuntimeIdentity {
    /// Tauri 框架版本（`tauri::VERSION`，即 tauri crate 编译期 `CARGO_PKG_VERSION`）。
    pub tauri_version: String,
    /// Rust toolchain 版本承诺（`CARGO_PKG_RUST_VERSION`；Cargo.toml 未声明
    /// `rust-version` 时为 `"unknown"`）。
    pub rust_version: String,
}

pub struct SkillPin {
    /// 技能 id（目录名）。
    pub skill_id: String,
    /// 技能声明版本（SKILL.md / tap 目录解析值；无则 `None`）。
    #[serde(skip_serializing_if = "Option::is_none")]
    pub version: Option<String>,
    /// 技能内容 hash（安装/更新链路产出的 content hash；无则 `None`）。
    #[serde(skip_serializing_if = "Option::is_none")]
    pub content_hash: Option<String>,
}

pub struct RolePackPin {
    /// 角色包 id。
    pub pack_id: String,
    /// 角色包版本（`role_packs` 注册表解析结果）。
    pub version: String,
}

pub struct EnvironmentManifest {
    pub schema_version: u16,
    /// OS/架构身份。
    pub os: OsIdentity,
    /// 应用版本（`dstu_core::APP_VERSION`，即根包 `deep-student` 的版本）。
    pub app_version: String,
    /// 运行时身份（tauri/rust 编译期版本）。
    pub runtime: RuntimeIdentity,
    /// G01-c 工具注册表全表指纹（见模块文档"指纹方案"）。
    pub tool_schema_hash: String,
    /// 指纹覆盖的工具条数（hash 之外的可读摘要，便于人眼核对）。
    pub tool_count: usize,
    /// 本次任务模型 id。
    #[serde(skip_serializing_if = "Option::is_none")]
    pub model_id: Option<String>,
    /// 已加载技能钉版（按 `skill_id` 排序，确定性）。
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub skills_loaded: Vec<SkillPin>,
    /// 角色包钉版（如有）。
    #[serde(skip_serializing_if = "Option::is_none")]
    pub role_pack: Option<RolePackPin>,
    /// 网络允许清单快照（排序去重，确定性）。
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub network_allowlist: Vec<String>,
    /// 工作目录身份快照（root id，排序去重，确定性）。
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub workspace_root_ids: Vec<String>,
    /// 采集时刻（RFC3339）。**不参与**内容指纹与漂移比对。
    pub captured_at: String,
}

pub enum EnvDriftField {
    /// 清单结构版本不同（跨版本比对，解读需谨慎）。
    SchemaVersion,
    /// OS/架构/族任一变化。
    Os,
    /// 应用版本变化。
    AppVersion,
    /// tauri/rust 版本任一变化。
    Runtime,
    /// 工具注册表指纹变化（工具增删/元数据调整）。
    ToolSchema,
    /// 模型 id 变化。
    Model,
    /// 技能集合或任一技能的 version/hash 变化。
    Skills,
    /// 角色包变化。
    RolePack,
    /// 网络允许清单变化。
    NetworkAllowlist,
    /// 工作目录身份变化。
    WorkspaceRoots,
}

pub struct EnvDrift {
    /// 漂移字段。
    pub field: EnvDriftField,
    /// 人类可读的确定性差异说明（`'baseline' -> 'current'`，
    /// 集合差异为 `+[added] -[removed]`）。
    pub detail: String,
}

pub enum ChatV2Error {
    /// 会话未找到
    #[error("Session not found: {0}")]
    SessionNotFound(String),

    /// 分组未找到
    #[error("Group not found: {0}")]
    GroupNotFound(String),

    /// 消息未找到
    #[error("Message not found: {0}")]
    MessageNotFound(String),

    /// 块未找到
    #[error("Block not found: {0}")]
    BlockNotFound(String),

    /// 资源未找到
    #[error("Resource not found: {0}")]
    ResourceNotFound(String),

    /// 变体未找到
    #[error("Variant not found: {0}")]
    VariantNotFound(String),

    /// 不能激活失败状态的变体
    #[error("Cannot activate failed variant: {0}")]
    VariantCannotActivateFailed(String),

    /// 不能删除最后一个变体
    #[error("Cannot delete last variant")]
    VariantCannotDeleteLast,

    /// 变体正在流式生成中
    #[error("Variant already streaming: {0}")]
    VariantAlreadyStreaming(String),

    /// 变体无法重试（非 error/cancelled 状态）
    #[error("Cannot retry variant: {0}, current status: {1}")]
    VariantCannotRetry(String, String),

    /// 变体数量超过限制
    #[error("Limit exceeded: {0}")]
    LimitExceeded(String),

    /// 数据库错误
    #[error("Database error: {0}")]
    Database(String),

    /// LLM 调用错误
    #[error("LLM error: {0}")]
    Llm(String),

    #[error("{message}")]
    ContextWindowExceeded {
        message: String,
        details: serde_json::Value,
    },

    /// 工具调用错误
    #[error("Tool error: {0}")]
    Tool(String),

    /// 操作被取消
    #[error("Cancelled")]
    Cancelled,

    /// 序列化/反序列化错误
    #[error("Serialization error: {0}")]
    Serialization(String),

    /// 验证错误
    #[error("Validation error: {0}")]
    Validation(String),

    /// 其他错误
    #[error("{0}")]
    Other(String),

    /// IO 错误（文件系统操作等）
    #[error("IO error: {0}")]
    IoError(String),

    /// 无效输入
    #[error("Invalid input: {0}")]
    InvalidInput(String),

    /// 数据库损坏（迁移失败且回滚也失败）
    #[error("DATABASE CORRUPTED - Original error: {original_error}, Rollback error: {rollback_error}. Database may be in inconsistent state.")]
    DatabaseCorrupted {
        original_error: String,
        rollback_error: String,
    },

    /// 工具执行超时
    #[error("Tool execution timeout: {0}")]
    Timeout(String),
}

pub struct BackendEvent {
    /// 递增序列号（用于前端检测乱序和丢失）
    /// 从 0 开始递增，每个会话的 EventEmitter 独立计数
    pub sequence_id: u64,

    /// 会话 ID（用于事件桥与调试）
    #[serde(skip_serializing_if = "Option::is_none")]
    pub session_id: Option<String>,

    /// 事件类型（如 'content', 'thinking', 'rag', 'tool_call', 'anki_cards', 'variant_start', 'variant_end'）
    pub r#type: String,

    /// 事件阶段：'start' | 'chunk' | 'end' | 'error'
    pub phase: String,

    /// 关联的消息 ID（start 阶段必须提供）
    #[serde(skip_serializing_if = "Option::is_none")]
    pub message_id: Option<String>,

    /// 关联的块 ID
    /// - start 阶段：可选，多工具并发时由后端生成并传入
    /// - chunk/end/error 阶段：必填
    #[serde(skip_serializing_if = "Option::is_none")]
    pub block_id: Option<String>,

    /// 块类型（start 阶段可选，默认使用 type）
    #[serde(skip_serializing_if = "Option::is_none")]
    pub block_type: Option<String>,

    /// 数据块（chunk 阶段）
    #[serde(skip_serializing_if = "Option::is_none")]
    pub chunk: Option<String>,

    /// 最终结果（end 阶段，如检索结果、工具输出）
    #[serde(skip_serializing_if = "Option::is_none")]
    pub result: Option<Value>,

    /// 错误信息（error 阶段）
    #[serde(skip_serializing_if = "Option::is_none")]
    pub error: Option<String>,

    /// 附加数据（任意阶段，如 toolName, toolInput）
    #[serde(skip_serializing_if = "Option::is_none")]
    pub payload: Option<Value>,

    /// 技能状态版本（用于丢弃过期事件）
    #[serde(skip_serializing_if = "Option::is_none")]
    pub skill_state_version: Option<u64>,

    /// 工具轮次 ID（用于多轮 tool loop 对齐）
    #[serde(skip_serializing_if = "Option::is_none")]
    pub round_id: Option<String>,

    // ========== 多变体支持字段 ==========
    /// 变体 ID（多变体模式下必填，单变体模式可选）
    #[serde(skip_serializing_if = "Option::is_none")]
    pub variant_id: Option<String>,

    /// 模型 ID（variant_start 事件时使用）
    #[serde(skip_serializing_if = "Option::is_none")]
    pub model_id: Option<String>,

    /// 变体状态（variant_end 事件时使用：success/error/cancelled）
    #[serde(skip_serializing_if = "Option::is_none")]
    pub status: Option<String>,

    /// Token 使用统计（variant_end 事件时使用）
    #[serde(skip_serializing_if = "Option::is_none")]
    pub usage: Option<TokenUsage>,
}

pub struct SessionEvent {
    /// 🆕 递增序列号（会话级通道独立计数，从 0 开始）
    /// 用于前端检测会话级事件的乱序/丢失。与块级事件的 sequence_id
    /// 各自独立计数（避免两个通道互相制造「空洞」误报丢事件）。
    /// Option 仅为反序列化旧事件兼容；后端发射时恒为 Some。
    #[serde(skip_serializing_if = "Option::is_none")]
    pub sequence_id: Option<u64>,

    /// 会话 ID
    pub session_id: String,

    /// 事件类型：stream_start/stream_complete/stream_error/stream_cancelled/save_complete/save_error
    pub event_type: String,

    /// 关联的消息 ID（可选）
    #[serde(skip_serializing_if = "Option::is_none")]
    pub message_id: Option<String>,

    /// Backend stream registration generation. Clients use this to reject terminal events from a
    /// cancelled run after an immediate retry has reused the same message ID.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub stream_generation: Option<u64>,

    /// Skill 状态版本
    #[serde(skip_serializing_if = "Option::is_none")]
    pub skill_state_version: Option<u64>,

    /// 历史重放模式
    #[serde(skip_serializing_if = "Option::is_none")]
    pub replay_mode: Option<String>,

    /// 模型标识符（stream_start 事件时提供，用于前端显示）
    #[serde(skip_serializing_if = "Option::is_none")]
    pub model_id: Option<String>,

    /// 重连/重试进度（stream_reconnect 事件时提供）
    #[serde(skip_serializing_if = "Option::is_none")]
    pub retry_attempt: Option<u32>,

    /// 最大重连/重试次数（stream_reconnect 事件时提供）
    #[serde(skip_serializing_if = "Option::is_none")]
    pub retry_max: Option<u32>,

    /// 错误信息（error 事件时提供）
    #[serde(skip_serializing_if = "Option::is_none")]
    pub error: Option<String>,

    /// 持续时间（毫秒，complete 事件时提供）
    #[serde(skip_serializing_if = "Option::is_none")]
    pub duration_ms: Option<u64>,

    /// 事件时间戳（毫秒）
    pub timestamp: i64,

    /// Token 使用统计（stream_complete 事件时提供）
    #[serde(skip_serializing_if = "Option::is_none")]
    pub usage: Option<TokenUsage>,

    /// 标题（summary_updated 事件时提供）
    #[serde(skip_serializing_if = "Option::is_none")]
    pub title: Option<String>,

    /// 简介（summary_updated 事件时提供）
    #[serde(skip_serializing_if = "Option::is_none")]
    pub description: Option<String>,

    /// 🆕 通用附加数据（compaction_failed / context_trimmed 等事件使用）。
    /// `skip_serializing_if` 保持既有事件序列化形态不变（向后兼容）。
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub payload: Option<Value>,
}

pub enum FinalizationVerdict {
    /// 所有已执行检查通过：申报产物全部存在且哈希匹配（或任务本无产物要求）
    VerifiedComplete,
    /// 任务完成但存在例外项（如产物存在但哈希与申报不符）
    CompleteWithExceptions,
    /// 部分完成：申报的产物缺失 / 申报本身非法
    Partial,
    /// 验收受阻：检查器已运行但无法完成核查（root 未配置 / IO 失败）
    Blocked,
    /// 无法判定：验收基础设施缺失（如无 AppHandle / 主库，检查器无法运行）
    OutcomeUnknown,
}

pub enum ExceptionKind {
    /// 申报的产物在对应 runtime root 下不存在
    ArtifactMissing,
    /// 产物存在但 SHA-256 与申报不符
    HashMismatch,
    /// 申报本身非法（绝对路径 / 父目录逃逸 / 空路径 / 非普通文件）
    InvalidDeclaration,
    /// 检查器无法完成核查（root 解析失败 / IO 错误 / 账本查询失败）
    CheckUnavailable,
    /// 批次清单缺项：接受时分母中的条目未成功产出或无记录产出（G07-b）
    BatchItemMissing,
    /// 外部副作用未决：connector 操作停在 submitting / outcome_unknown（G07-b）
    SideEffectPending,
}

pub struct FinalizationException {
    /// 产生该例外的检查器 id（如 `artifacts_exist`）
    pub check: String,
    pub kind: ExceptionKind,
    /// 相关产物路径（如适用）
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub path: Option<String>,
    /// 人类可读原因
    pub message: String,
}

pub struct FinalizationReport {
    pub verdict: FinalizationVerdict,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub exceptions: Vec<FinalizationException>,
    /// 实际执行的检查器 id 列表
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub checks_run: Vec<String>,
}

pub struct DeclaredArtifact {
    /// 产物相对路径（相对对应 runtime root；拒绝绝对路径与 `..`）
    pub path: String,
    /// 可选：产物内容 SHA-256（hex，大小写不敏感）；申报即校验
    #[serde(default)]
