    /// （见 `FsrsFeedbackConfig::include_card_excerpts`）。
    /// 统计查询只读本地 SQLite；查询失败时降级为不注入，绝不阻断制卡。
    #[serde(default)]
    pub fsrs_feedback: Option<bool>,
