    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub enable_critic_pass: Option<bool>,
    /// `enable_critic_pass` 的兼容别名；任一开关为 true 即启用。
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub enable_llm_critic: Option<bool>,
    /// critic prompt 的 token 预算覆盖；`None` 使用模块默认值。
    #[serde(default, skip_serializing_if = "Option::is_none")]
