    pub objects_checked: usize,
    /// 完整校验累计的字节数
    pub bytes_verified: u64,
    /// 孤儿对象总数（含未列入 `problems` 的部分）
    pub orphan_objects: usize,
    /// 问题明细（最多 [`MAX_REPORTED_PROBLEMS`] 条）
    pub problems: Vec<RepoCheckProblem>,
