    Audio,
    /// 视频（取音轨转写，阶段同音频）
    Video,
}

pub enum ProcessingStage {
    /// 等待处理
    Pending,
    /// 文本提取中（PDF 专用）
    TextExtraction,
    /// 页面渲染中（PDF 专用）
    PageRendering,
    /// 页面压缩中（PDF 专用）
    PageCompression,
    /// 图片压缩中（图片专用）
    ImageCompression,
    /// OCR 处理中（PDF 多页 / 图片单张）
    OcrProcessing,
    /// 向量索引中
    VectorIndexing,
    /// 处理完成
    Completed,
    /// 处理完成但存在可重试问题（如 OCR/向量索引部分失败）
    CompletedWithIssues,
    /// 处理失败
    Error,
    /// 音视频：排队等待全局转写槽位
    Queued,
    /// 音视频：解码为 16 kHz 单声道
    Decode,
    /// 音视频：语音活动检测与分段
    Vad,
    /// 音视频：逐段语音识别
    Asr,
    /// 音视频：转写文本索引
    Indexing,
}

